CREATE TYPE "ProductStatus" AS ENUM ('candidate','under_review','approved','test','rejected','active','paused','retired');
CREATE TYPE "PublicationStatus" AS ENUM ('draft','awaiting_approval','approved','scheduled','publishing','published','failed','cancelled');
CREATE TYPE "ContentStatus" AS ENUM ('draft','ready','archived');
CREATE TYPE "CreativeAssetStatus" AS ENUM ('draft','ready','archived');
CREATE TYPE "PlanStatus" AS ENUM ('draft','active','completed','cancelled');
CREATE TYPE "RunStatus" AS ENUM ('pending','running','succeeded','failed','cancelled');
CREATE TYPE "IntegrationStatus" AS ENUM ('disconnected','connected','degraded','revoked');
CREATE TYPE "CapabilityStatus" AS ENUM ('unavailable','available','limited');

CREATE TABLE "Workspace" ("id" UUID PRIMARY KEY, "name" TEXT NOT NULL, "slug" TEXT NOT NULL UNIQUE, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Category" ("id" UUID PRIMARY KEY, "workspaceId" UUID NOT NULL, "name" TEXT NOT NULL, "slug" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Category_workspaceId_fkey" FOREIGN KEY ("workspaceId") REFERENCES "Workspace"("id") ON DELETE CASCADE);
CREATE UNIQUE INDEX "Category_workspaceId_slug_key" ON "Category"("workspaceId","slug");
CREATE INDEX "Category_workspaceId_idx" ON "Category"("workspaceId");
CREATE TABLE "Seller" ("id" UUID PRIMARY KEY, "workspaceId" UUID NOT NULL, "marketplace" TEXT NOT NULL, "externalId" TEXT NOT NULL, "name" TEXT, "reputation" DECIMAL(5,2), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Seller_workspaceId_fkey" FOREIGN KEY ("workspaceId") REFERENCES "Workspace"("id") ON DELETE CASCADE);
CREATE UNIQUE INDEX "Seller_workspaceId_marketplace_externalId_key" ON "Seller"("workspaceId","marketplace","externalId");
CREATE TABLE "Product" ("id" UUID PRIMARY KEY, "workspaceId" UUID NOT NULL, "marketplace" TEXT NOT NULL, "externalId" TEXT NOT NULL, "name" TEXT NOT NULL, "description" TEXT, "categoryId" UUID, "canonicalUrl" TEXT NOT NULL, "affiliateUrl" TEXT, "price" DECIMAL(14,2), "currency" TEXT, "rating" DECIMAL(3,2), "reviewCount" INTEGER, "salesCount" INTEGER, "sellerId" UUID, "availability" TEXT, "thumbnailUrl" TEXT, "status" "ProductStatus" NOT NULL DEFAULT 'candidate', "firstSeenAt" TIMESTAMP(3) NOT NULL, "lastCheckedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Product_workspaceId_fkey" FOREIGN KEY ("workspaceId") REFERENCES "Workspace"("id") ON DELETE CASCADE, CONSTRAINT "Product_categoryId_fkey" FOREIGN KEY ("categoryId") REFERENCES "Category"("id") ON DELETE SET NULL, CONSTRAINT "Product_sellerId_fkey" FOREIGN KEY ("sellerId") REFERENCES "Seller"("id") ON DELETE SET NULL);
CREATE UNIQUE INDEX "Product_workspaceId_marketplace_externalId_key" ON "Product"("workspaceId","marketplace","externalId");
CREATE INDEX "Product_workspaceId_status_idx" ON "Product"("workspaceId","status");
CREATE INDEX "Product_categoryId_idx" ON "Product"("categoryId");
CREATE TABLE "ProductResearchRun" ("id" UUID PRIMARY KEY, "workspaceId" UUID NOT NULL, "query" TEXT NOT NULL, "status" "RunStatus" NOT NULL DEFAULT 'pending', "startedAt" TIMESTAMP(3), "completedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "ProductResearchRun_workspaceId_fkey" FOREIGN KEY ("workspaceId") REFERENCES "Workspace"("id") ON DELETE CASCADE);
CREATE INDEX "ProductResearchRun_workspaceId_createdAt_idx" ON "ProductResearchRun"("workspaceId","createdAt");
CREATE TABLE "ProductCandidate" ("id" UUID PRIMARY KEY, "researchRunId" UUID NOT NULL, "productId" UUID, "categoryId" UUID, "marketplace" TEXT NOT NULL, "externalId" TEXT NOT NULL, "sourceUrl" TEXT NOT NULL, "capturedData" JSONB NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "ProductCandidate_researchRunId_fkey" FOREIGN KEY ("researchRunId") REFERENCES "ProductResearchRun"("id") ON DELETE CASCADE, CONSTRAINT "ProductCandidate_productId_fkey" FOREIGN KEY ("productId") REFERENCES "Product"("id") ON DELETE SET NULL, CONSTRAINT "ProductCandidate_categoryId_fkey" FOREIGN KEY ("categoryId") REFERENCES "Category"("id") ON DELETE SET NULL);
CREATE UNIQUE INDEX "ProductCandidate_researchRunId_marketplace_externalId_key" ON "ProductCandidate"("researchRunId","marketplace","externalId");
CREATE TABLE "ProductComparison" ("id" UUID PRIMARY KEY, "researchRunId" UUID NOT NULL, "productId" UUID NOT NULL, "position" INTEGER, "notes" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "ProductComparison_researchRunId_fkey" FOREIGN KEY ("researchRunId") REFERENCES "ProductResearchRun"("id") ON DELETE CASCADE, CONSTRAINT "ProductComparison_productId_fkey" FOREIGN KEY ("productId") REFERENCES "Product"("id") ON DELETE CASCADE);
CREATE UNIQUE INDEX "ProductComparison_researchRunId_productId_key" ON "ProductComparison"("researchRunId","productId");
CREATE TABLE "ProductScore" ("id" UUID PRIMARY KEY, "productId" UUID NOT NULL, "score" DECIMAL(5,2) NOT NULL, "confidence" DECIMAL(5,4) NOT NULL, "availableFactors" TEXT[] NOT NULL, "missingFactors" TEXT[] NOT NULL, "factorScores" JSONB NOT NULL, "explanation" TEXT NOT NULL, "calculatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "ProductScore_productId_fkey" FOREIGN KEY ("productId") REFERENCES "Product"("id") ON DELETE CASCADE);
CREATE INDEX "ProductScore_productId_calculatedAt_idx" ON "ProductScore"("productId","calculatedAt");
CREATE TABLE "AffiliateLink" ("id" UUID PRIMARY KEY, "productId" UUID NOT NULL, "provider" TEXT NOT NULL, "url" TEXT NOT NULL, "externalId" TEXT, "active" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "AffiliateLink_productId_fkey" FOREIGN KEY ("productId") REFERENCES "Product"("id") ON DELETE CASCADE);
CREATE UNIQUE INDEX "AffiliateLink_productId_provider_url_key" ON "AffiliateLink"("productId","provider","url");
CREATE TABLE "Content" ("id" UUID PRIMARY KEY, "workspaceId" UUID NOT NULL, "productId" UUID, "title" TEXT NOT NULL, "body" TEXT NOT NULL, "status" "ContentStatus" NOT NULL DEFAULT 'draft', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Content_workspaceId_fkey" FOREIGN KEY ("workspaceId") REFERENCES "Workspace"("id") ON DELETE CASCADE, CONSTRAINT "Content_productId_fkey" FOREIGN KEY ("productId") REFERENCES "Product"("id") ON DELETE SET NULL);
CREATE TABLE "ContentVariant" ("id" UUID PRIMARY KEY, "contentId" UUID NOT NULL, "channel" TEXT NOT NULL, "title" TEXT, "body" TEXT NOT NULL, "metadata" JSONB, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "ContentVariant_contentId_fkey" FOREIGN KEY ("contentId") REFERENCES "Content"("id") ON DELETE CASCADE);
CREATE INDEX "ContentVariant_contentId_channel_idx" ON "ContentVariant"("contentId","channel");
CREATE TABLE "CreativeAsset" ("id" UUID PRIMARY KEY, "workspaceId" UUID NOT NULL, "contentId" UUID, "kind" TEXT NOT NULL, "storageKey" TEXT NOT NULL, "mimeType" TEXT NOT NULL, "width" INTEGER, "height" INTEGER, "status" "CreativeAssetStatus" NOT NULL DEFAULT 'draft', "metadata" JSONB, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "CreativeAsset_workspaceId_fkey" FOREIGN KEY ("workspaceId") REFERENCES "Workspace"("id") ON DELETE CASCADE, CONSTRAINT "CreativeAsset_contentId_fkey" FOREIGN KEY ("contentId") REFERENCES "Content"("id") ON DELETE SET NULL);
CREATE TABLE "WeeklyPlan" ("id" UUID PRIMARY KEY, "workspaceId" UUID NOT NULL, "weekStartsOn" DATE NOT NULL, "status" "PlanStatus" NOT NULL DEFAULT 'draft', "goals" JSONB, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "WeeklyPlan_workspaceId_fkey" FOREIGN KEY ("workspaceId") REFERENCES "Workspace"("id") ON DELETE CASCADE);
CREATE UNIQUE INDEX "WeeklyPlan_workspaceId_weekStartsOn_key" ON "WeeklyPlan"("workspaceId","weekStartsOn");
CREATE TABLE "DailyPlan" ("id" UUID PRIMARY KEY, "workspaceId" UUID NOT NULL, "weeklyPlanId" UUID, "planDate" DATE NOT NULL, "status" "PlanStatus" NOT NULL DEFAULT 'draft', "goals" JSONB, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "DailyPlan_workspaceId_fkey" FOREIGN KEY ("workspaceId") REFERENCES "Workspace"("id") ON DELETE CASCADE, CONSTRAINT "DailyPlan_weeklyPlanId_fkey" FOREIGN KEY ("weeklyPlanId") REFERENCES "WeeklyPlan"("id") ON DELETE SET NULL);
CREATE UNIQUE INDEX "DailyPlan_workspaceId_planDate_key" ON "DailyPlan"("workspaceId","planDate");
CREATE TABLE "PublicationQueueItem" ("id" UUID PRIMARY KEY, "workspaceId" UUID NOT NULL, "productId" UUID, "contentId" UUID NOT NULL, "contentVariantId" UUID, "creativeAssetId" UUID, "channel" TEXT NOT NULL, "status" "PublicationStatus" NOT NULL DEFAULT 'draft', "scheduledFor" TIMESTAMP(3), "approvedAt" TIMESTAMP(3), "approvedBy" TEXT, "attempts" INTEGER NOT NULL DEFAULT 0, "lastError" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "PublicationQueueItem_workspaceId_fkey" FOREIGN KEY ("workspaceId") REFERENCES "Workspace"("id") ON DELETE CASCADE, CONSTRAINT "PublicationQueueItem_productId_fkey" FOREIGN KEY ("productId") REFERENCES "Product"("id") ON DELETE SET NULL, CONSTRAINT "PublicationQueueItem_contentId_fkey" FOREIGN KEY ("contentId") REFERENCES "Content"("id") ON DELETE RESTRICT, CONSTRAINT "PublicationQueueItem_contentVariantId_fkey" FOREIGN KEY ("contentVariantId") REFERENCES "ContentVariant"("id") ON DELETE SET NULL, CONSTRAINT "PublicationQueueItem_creativeAssetId_fkey" FOREIGN KEY ("creativeAssetId") REFERENCES "CreativeAsset"("id") ON DELETE SET NULL);
CREATE INDEX "PublicationQueueItem_workspaceId_status_scheduledFor_idx" ON "PublicationQueueItem"("workspaceId","status","scheduledFor");
CREATE TABLE "Publication" ("id" UUID PRIMARY KEY, "workspaceId" UUID NOT NULL, "queueItemId" UUID NOT NULL UNIQUE, "productId" UUID, "contentId" UUID NOT NULL, "contentVariantId" UUID, "channel" TEXT NOT NULL, "status" "PublicationStatus" NOT NULL, "externalId" TEXT, "externalUrl" TEXT, "publishedAt" TIMESTAMP(3), "failureReason" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Publication_workspaceId_fkey" FOREIGN KEY ("workspaceId") REFERENCES "Workspace"("id") ON DELETE CASCADE, CONSTRAINT "Publication_queueItemId_fkey" FOREIGN KEY ("queueItemId") REFERENCES "PublicationQueueItem"("id") ON DELETE RESTRICT, CONSTRAINT "Publication_productId_fkey" FOREIGN KEY ("productId") REFERENCES "Product"("id") ON DELETE SET NULL, CONSTRAINT "Publication_contentId_fkey" FOREIGN KEY ("contentId") REFERENCES "Content"("id") ON DELETE RESTRICT, CONSTRAINT "Publication_contentVariantId_fkey" FOREIGN KEY ("contentVariantId") REFERENCES "ContentVariant"("id") ON DELETE SET NULL);
CREATE TABLE "MetricSnapshot" ("id" UUID PRIMARY KEY, "workspaceId" UUID NOT NULL, "publicationId" UUID, "productId" UUID, "source" TEXT NOT NULL, "observedAt" TIMESTAMP(3) NOT NULL, "impressions" INTEGER, "clicks" INTEGER, "saves" INTEGER, "conversions" INTEGER, "revenue" DECIMAL(14,2), "currency" TEXT, "rawData" JSONB, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "MetricSnapshot_workspaceId_fkey" FOREIGN KEY ("workspaceId") REFERENCES "Workspace"("id") ON DELETE CASCADE, CONSTRAINT "MetricSnapshot_publicationId_fkey" FOREIGN KEY ("publicationId") REFERENCES "Publication"("id") ON DELETE SET NULL, CONSTRAINT "MetricSnapshot_productId_fkey" FOREIGN KEY ("productId") REFERENCES "Product"("id") ON DELETE SET NULL);
CREATE INDEX "MetricSnapshot_workspaceId_source_observedAt_idx" ON "MetricSnapshot"("workspaceId","source","observedAt");
CREATE TABLE "Conversion" ("id" UUID PRIMARY KEY, "workspaceId" UUID NOT NULL, "publicationId" UUID, "productId" UUID, "source" TEXT NOT NULL, "externalId" TEXT, "occurredAt" TIMESTAMP(3) NOT NULL, "amount" DECIMAL(14,2), "commission" DECIMAL(14,2), "currency" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Conversion_workspaceId_fkey" FOREIGN KEY ("workspaceId") REFERENCES "Workspace"("id") ON DELETE CASCADE, CONSTRAINT "Conversion_publicationId_fkey" FOREIGN KEY ("publicationId") REFERENCES "Publication"("id") ON DELETE SET NULL, CONSTRAINT "Conversion_productId_fkey" FOREIGN KEY ("productId") REFERENCES "Product"("id") ON DELETE SET NULL);
CREATE UNIQUE INDEX "Conversion_workspaceId_source_externalId_key" ON "Conversion"("workspaceId","source","externalId");
CREATE TABLE "Experiment" ("id" UUID PRIMARY KEY, "workspaceId" UUID NOT NULL, "name" TEXT NOT NULL, "hypothesis" TEXT NOT NULL, "status" TEXT NOT NULL, "startsAt" TIMESTAMP(3), "endsAt" TIMESTAMP(3), "configuration" JSONB NOT NULL, "result" JSONB, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Experiment_workspaceId_fkey" FOREIGN KEY ("workspaceId") REFERENCES "Workspace"("id") ON DELETE CASCADE);
CREATE TABLE "Strategy" ("id" UUID PRIMARY KEY, "workspaceId" UUID NOT NULL, "name" TEXT NOT NULL, "version" INTEGER NOT NULL DEFAULT 1, "active" BOOLEAN NOT NULL DEFAULT false, "configuration" JSONB NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Strategy_workspaceId_fkey" FOREIGN KEY ("workspaceId") REFERENCES "Workspace"("id") ON DELETE CASCADE);
CREATE UNIQUE INDEX "Strategy_workspaceId_name_version_key" ON "Strategy"("workspaceId","name","version");
CREATE TABLE "StrategyDecision" ("id" UUID PRIMARY KEY, "strategyId" UUID NOT NULL, "decisionType" TEXT NOT NULL, "subjectType" TEXT NOT NULL, "subjectId" TEXT, "rationale" TEXT NOT NULL, "inputs" JSONB NOT NULL, "outcome" JSONB, "decidedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "StrategyDecision_strategyId_fkey" FOREIGN KEY ("strategyId") REFERENCES "Strategy"("id") ON DELETE CASCADE);
CREATE INDEX "StrategyDecision_strategyId_decidedAt_idx" ON "StrategyDecision"("strategyId","decidedAt");
CREATE TABLE "IntegrationAccount" ("id" UUID PRIMARY KEY, "workspaceId" UUID NOT NULL, "provider" TEXT NOT NULL, "externalAccountId" TEXT, "displayName" TEXT, "status" "IntegrationStatus" NOT NULL DEFAULT 'disconnected', "accessTokenCiphertext" BYTEA, "accessTokenIv" BYTEA, "accessTokenAuthTag" BYTEA, "refreshTokenCiphertext" BYTEA, "refreshTokenIv" BYTEA, "refreshTokenAuthTag" BYTEA, "tokenExpiresAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "IntegrationAccount_workspaceId_fkey" FOREIGN KEY ("workspaceId") REFERENCES "Workspace"("id") ON DELETE CASCADE);
CREATE UNIQUE INDEX "IntegrationAccount_workspaceId_provider_externalAccountId_key" ON "IntegrationAccount"("workspaceId","provider","externalAccountId");
CREATE TABLE "IntegrationCapability" ("id" UUID PRIMARY KEY, "integrationAccountId" UUID NOT NULL, "capability" TEXT NOT NULL, "status" "CapabilityStatus" NOT NULL DEFAULT 'unavailable', "checkedAt" TIMESTAMP(3), "details" JSONB, CONSTRAINT "IntegrationCapability_integrationAccountId_fkey" FOREIGN KEY ("integrationAccountId") REFERENCES "IntegrationAccount"("id") ON DELETE CASCADE);
CREATE UNIQUE INDEX "IntegrationCapability_integrationAccountId_capability_key" ON "IntegrationCapability"("integrationAccountId","capability");
CREATE TABLE "AgentSession" ("id" UUID PRIMARY KEY, "workspaceId" UUID NOT NULL, "agentName" TEXT NOT NULL, "startedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "endedAt" TIMESTAMP(3), CONSTRAINT "AgentSession_workspaceId_fkey" FOREIGN KEY ("workspaceId") REFERENCES "Workspace"("id") ON DELETE CASCADE);
CREATE TABLE "ConversationMessage" ("id" UUID PRIMARY KEY, "agentSessionId" UUID NOT NULL, "role" TEXT NOT NULL, "content" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "ConversationMessage_agentSessionId_fkey" FOREIGN KEY ("agentSessionId") REFERENCES "AgentSession"("id") ON DELETE CASCADE);
CREATE INDEX "ConversationMessage_agentSessionId_createdAt_idx" ON "ConversationMessage"("agentSessionId","createdAt");
CREATE TABLE "AgentRun" ("id" UUID PRIMARY KEY, "agentSessionId" UUID NOT NULL, "status" "RunStatus" NOT NULL DEFAULT 'pending', "objective" TEXT NOT NULL, "startedAt" TIMESTAMP(3), "completedAt" TIMESTAMP(3), "errorCode" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "AgentRun_agentSessionId_fkey" FOREIGN KEY ("agentSessionId") REFERENCES "AgentSession"("id") ON DELETE CASCADE);
CREATE TABLE "ToolExecution" ("id" UUID PRIMARY KEY, "agentRunId" UUID NOT NULL, "toolName" TEXT NOT NULL, "status" "RunStatus" NOT NULL DEFAULT 'pending', "input" JSONB NOT NULL, "output" JSONB, "errorCode" TEXT, "startedAt" TIMESTAMP(3), "completedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "ToolExecution_agentRunId_fkey" FOREIGN KEY ("agentRunId") REFERENCES "AgentRun"("id") ON DELETE CASCADE);
CREATE INDEX "ToolExecution_agentRunId_createdAt_idx" ON "ToolExecution"("agentRunId","createdAt");
CREATE TABLE "AuditLog" ("id" UUID PRIMARY KEY, "workspaceId" UUID NOT NULL, "actorType" TEXT NOT NULL, "actorId" TEXT, "action" TEXT NOT NULL, "resourceType" TEXT NOT NULL, "resourceId" TEXT, "metadata" JSONB, "occurredAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "AuditLog_workspaceId_fkey" FOREIGN KEY ("workspaceId") REFERENCES "Workspace"("id") ON DELETE CASCADE);
CREATE INDEX "AuditLog_workspaceId_occurredAt_idx" ON "AuditLog"("workspaceId","occurredAt");
